import 'dart:math' as math;
import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/models.dart';
import '../services/storage_service.dart';
import '../widgets/app_card.dart';

const List<String> expenseCategories=<String>['Alimentação','Transporte','Moradia','Lazer','Educação','Saúde','Compras','Outros'];
const List<String> incomeCategories=<String>['Salário','Freelance','Investimentos','Outros'];

class FinanceScreen extends StatefulWidget{const FinanceScreen({super.key});@override State<FinanceScreen> createState()=>_FinanceScreenState();}
class _FinanceScreenState extends State<FinanceScreen>{List<MoneyTransaction> items=[];DateTime month=DateTime(DateTime.now().year,DateTime.now().month);@override void initState(){super.initState();_load();}Future<void> _load()async{try{final data=await StorageService.read('finance');items=data.map(MoneyTransaction.fromJson).toList();}catch(_){items=[];}if(mounted)setState((){});}Future<void> _save()=>StorageService.write('finance',items.map((e)=>e.toJson()).toList());double _sum(Iterable<MoneyTransaction> list,bool income)=>list.where((e)=>e.income==income).fold(0.0,(s,e)=>s+e.amount);
Future<void> _edit([MoneyTransaction? old])async{final d=TextEditingController(text:old?.description??''),a=TextEditingController(text:old==null?'':old.amount.toStringAsFixed(2));bool inc=old?.income??false;String cat=old?.category??'Outros';final result=await showDialog<bool>(context:context,builder:(dc)=>StatefulBuilder(builder:(ctx,setD){final cats=inc?incomeCategories:expenseCategories;if(!cats.contains(cat))cat='Outros';return AlertDialog(title:Text(old==null?'Nova movimentação':'Editar movimentação'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:d,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor',prefixText:r'R$ ')),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Entrada'),value:inc,onChanged:(v)=>setD((){inc=v;cat='Outros';})),DropdownButtonFormField<String>(isExpanded:true,initialValue:cat,items:cats.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)setD(()=>cat=v);},decoration:const InputDecoration(labelText:'Categoria'))])),actions:[TextButton(onPressed:()=>Navigator.pop(dc,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(dc,true),child:const Text('Salvar'))]));final value=double.tryParse(a.text.trim().replaceAll(',','.'));if(result!=true||d.text.trim().isEmpty||value==null||value<=0)return;final tx=MoneyTransaction(id:old?.id??DateTime.now().microsecondsSinceEpoch.toString(),date:old?.date??DateFormat('yyyy-MM-dd').format(DateTime.now()),description:d.text.trim(),category:cat,amount:value,income:inc);items.removeWhere((e)=>e.id==tx.id);items.add(tx);await _save();if(mounted)setState((){});}
Future<void> _delete(MoneyTransaction item)async{items.removeWhere((e)=>e.id==item.id);await _save();if(mounted)setState((){});}
@override Widget build(BuildContext context){final key=DateFormat('yyyy-MM').format(month);final current=items.where((e)=>e.date.startsWith(key)).toList();final income=_sum(current,true),expense=_sum(current,false),balance=_sum(items,true)-_sum(items,false);final byCat=<String,double>{};for(final e in current.where((e)=>!e.income)){byCat[e.category]=(byCat[e.category]??0)+e.amount;}return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Financeiro',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),IconButton(onPressed:_edit,icon:const Icon(Icons.add_circle_outline))]),AppCard(child:Row(children:[IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month-1)),icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat('MMMM yyyy','pt_BR').format(month),textAlign:TextAlign.center,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month+1)),icon:const Icon(Icons.chevron_right))])),Row(children:[Expanded(child:_metric('Entradas',income,Icons.arrow_downward)),Expanded(child:_metric('Despesas',expense,Icons.arrow_upward))]),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Saldo atual',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:6),Text(r'R$ '+balance.toStringAsFixed(2),style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:4),Text(r'Resultado do mês: R$ '+(income-expense).toStringAsFixed(2))])),if(current.isNotEmpty)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Distribuição das despesas',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),SizedBox(height:190,child:Row(children:[Expanded(child:DonutChart(values:byCat)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:byCat.entries.take(8).map((e)=>Padding(padding:const EdgeInsets.symmetric(vertical:3),child:Text('${e.key}: ${e.value.toStringAsFixed(2)}',maxLines:1,overflow:TextOverflow.ellipsis))).toList()))]))])),if(income+expense>0)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Entradas x despesas',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:10),SizedBox(height:130,child:DonutChart(values:{'Entradas':income,'Despesas':expense}))])),Text('Movimentações',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),if(current.isEmpty)const AppCard(child:Text('Nenhuma movimentação neste mês.')),...current.map((item)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,leading:CircleAvatar(child:Icon(item.income?Icons.add:Icons.remove)),title:Text(item.description),subtitle:Text('${item.category} • ${item.date.split('-').reversed.join('/')}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='edit')_edit(item);if(v=='delete')_delete(item);},itemBuilder:(c)=>const[PopupMenuItem(value:'edit',child:Text('Editar')),PopupMenuItem(value:'delete',child:Text('Excluir'))]))))]));}
Widget _metric(String label,double value,IconData icon)=>AppCard(child:Row(children:[Icon(icon,size:20),const SizedBox(width:8),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(r'R$ '+value.toStringAsFixed(2),style:const TextStyle(fontWeight:FontWeight.bold)),Text(label)]))]));}

class DonutChart extends StatelessWidget{final Map<String,double> values;const DonutChart({super.key,required this.values});@override Widget build(BuildContext context){return CustomPaint(painter:_DonutPainter(values,Theme.of(context).colorScheme.primary),size:const Size(double.infinity,180));}}
class _DonutPainter extends CustomPainter{final Map<String,double> values;final Color color;_DonutPainter(this.values,this.color);@override void paint(Canvas canvas,Size size){final total=values.values.fold(0.0,(s,v)=>s+v);if(total<=0)return;final center=Offset(size.width/2,size.height/2);final radius=math.min(size.width,size.height)*.35;final rect=Rect.fromCircle(center:center,radius:radius);var start=-math.pi/2;var index=0;final paint=Paint()..style=PaintingStyle.stroke..strokeWidth=28;for(final v in values.values){final sweep=2*math.pi*v/total;paint.color=Color.lerp(color,Colors.transparent,index/values.length)??color;canvas.drawArc(rect,start,sweep,false,paint);start+=sweep;index++;}final tp=TextPainter(text:TextSpan(text:'${total.toStringAsFixed(0)}',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold,color:color)),textDirection:TextDirection.ltr)..layout();tp.paint(canvas,center-Offset(tp.width/2,tp.height/2));} @override bool shouldRepaint(covariant _DonutPainter old)=>old.values!=values;}
